mapper.select:
SELECT o.id, o.user_id AS userId, o.accept_user_id AS acceptUserId, o.course_name AS courseName, o.course_type AS courseType, o.class_time AS classTime, o.location, o.salary, o.description, o.contact, o.status, o.view_count AS viewCount, o.create_time AS createTime, o.update_time AS updateTime, u1.nickname AS publisherNickname, u1.avatar AS publisherAvatar, u2.nickname AS acceptorNickname, u2.avatar AS acceptorAvatar FROM course_order o LEFT JOIN sys_user u1 ON o.user_id = u1.id LEFT JOIN sys_user u2 ON o.accept_user_id = u2.id
o.status = #{status}
ORDER BY CASE WHEN o.status IN (0, 1) THEN 0 ELSE 1 END, o.create_time DESC
